<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from "vue";

type ModuleName = "resume" | "knowledge" | "upgrade" | "targets" | "jobs";
type KnowledgeCategory = "个人信息" | "教育经历" | "工作经历" | "项目经验" | "技能" | "成果";
interface ResumeSource { id: number; filename: string; content: string; source_image_ids: number[]; created_at: string }
interface ResumeVersion { id: number; target_id: number | null; is_current: boolean; version: number; title: string; content: string; greeting: string; job_snapshot: { job_id?: number | null; job_title?: string; company?: string; jd_text?: string }; source_item_ids: number[]; source_resume_id: number | null }
interface KnowledgeItem { id: number; category: KnowledgeCategory; title: string; organization: string; period: string; content: string; source_note: string }
interface ResumeImage { id: number; filename: string; content_type: string }
interface StarExperience { title?: string; text: string; bullet_count?: number; missing: string[] }
interface QualityCheck { layout?: { status: string; message: string; estimated_lines: number; max_lines: number; estimated_pages: number }; star: { total_experiences?: number; total_items?: number; needs_follow_up: number; status: string; experiences?: StarExperience[]; items?: StarExperience[] }; diff: { added_lines: number; removed_lines: number; added_preview: string[]; removed_preview: string[] }; factuality?: { status: string; scope: string; items: { text: string; claims: string[] }[] } }
interface ResumeChunk { chunk_id: number; content: string; matched_terms: string[]; score: number; match_type: string }
interface Run { id: number; source_resume_id: number; status: string; result_content: string; greeting: string; error_message?: string; updated_at?: string; evidence: { knowledge_item_id?: number; resume_chunk_id?: number; used_for: string }[]; missing_info: string[]; input_snapshot: { job_id?: number | null; target_id?: number | null; job_title?: string; company?: string; jd_text?: string; instruction?: string; resume_chunks?: ResumeChunk[]; jd_analysis?: { responsibilities: string[]; hard_requirements: string[]; preferred_qualifications: string[]; keywords: string[] }; requirement_matches?: { category: string; requirement: string; status: string; evidence: { knowledge_item_id: number | null; title: string; matched_terms: string[] }[] }[]; quality_check?: QualityCheck; agent_graph?: { name: string; status: string; status_message: string } } }
interface Target { id: number; title: string; keywords: string; cities: string[]; is_active: boolean }
interface Job { id: number; target_id: number | null; target_title?: string | null; title: string; company: string; city: string; description: string; source: string; original_url: string; status: string; notes: string; next_action: string }
interface BossBrowserStatus { connected: boolean; url: string; title: string; logged_in: boolean | null; message: string }
interface BossSyncJob { title: string; company: string; city: string; description: string; raw_text?: string; warnings?: string[]; original_url: string; source: string; status: string }
interface BossSyncResult extends BossBrowserStatus { jobs: BossSyncJob[]; warnings: string[] }

const moduleNames: ModuleName[] = ["resume", "knowledge", "upgrade", "targets", "jobs"];
function moduleFromHash(hash: string): ModuleName {
  const value = hash.replace(/^#/, "");
  const legacyName = value.endsWith("-module") ? value.slice(0, -"-module".length) : value;
  return moduleNames.includes(legacyName as ModuleName) ? legacyName as ModuleName : "resume";
}
const active = ref<ModuleName>(moduleFromHash(location.hash));
const sources = ref<ResumeSource[]>([]); const images = ref<ResumeImage[]>([]); const knowledge = ref<KnowledgeItem[]>([]); const resumes = ref<ResumeVersion[]>([]); const runs = ref<Run[]>([]); const selectedJobId = ref<number | null>(null); const selectedResumeTargetId = ref<number | null>(null);
const targets = ref<Target[]>([]); const jobs = ref<Job[]>([]); const selectedSourceId = ref<number | null>(null); const selectedImageIds = ref<number[]>([]);
const sourceFilename = ref("手动粘贴"); const sourceDraft = ref(""); const transcript = ref(""); const notice = ref(""); const aiNotice = ref(""); const currentRun = ref<Run | null>(null); const consent = ref(false); const instruction = ref("");
const title = ref("AI 改进版简历"); const jdTitle = ref(""); const jdCompany = ref(""); const jdText = ref(""); const knowledgeCategory = ref<KnowledgeCategory>("教育经历"); const knowledgeTitle = ref(""); const knowledgeOrg = ref(""); const knowledgePeriod = ref(""); const knowledgeContent = ref(""); const knowledgeSource = ref("");
const editingKnowledgeId = ref<number | null>(null); const viewedResume = ref<ResumeVersion | null>(null);
const targetTitle = ref(""); const targetKeywords = ref(""); const targetCities = ref("北京,天津"); const jobTitle = ref(""); const jobCompany = ref(""); const jobCity = ref(""); const jobSource = ref("手动录入"); const jobUrl = ref(""); const jobStatus = ref("未处理"); const jobDescription = ref(""); const jobNotes = ref(""); const jobNextAction = ref(""); const jobTargetId = ref<number | null>(null); const editingJobId = ref<number | null>(null); const jobFilterStatus = ref("全部"); const jobSearch = ref("");
const bossTitle = ref(""); const bossCompany = ref(""); const bossCity = ref(""); const bossUrl = ref(""); const bossDescription = ref(""); const bossPastedText = ref(""); const bossParseNotice = ref(""); const bossTargetId = ref<number | null>(null);
const bossBrowser = ref<BossBrowserStatus>({ connected: false, url: "", title: "", logged_in: null, message: "Chrome 尚未连接。" }); const bossSyncJobs = ref<BossSyncJob[]>([]); const bossSyncNotice = ref("");
const deliveryJobId = ref<number | null>(null); const deliveryResumeId = ref<number | null>(null); const deliveryGreeting = ref(""); const deliveryNotice = ref(""); const greetingCopied = ref(false);
type FeedbackKind = "info" | "success" | "error";
const busy = ref<Record<string, boolean>>({});
const loading = ref(true);
const noticeKind = ref<FeedbackKind>("info");
const aiNoticeKind = ref<FeedbackKind>("info");
const guide = ref<{ text: string; to: ModuleName; toLabel: string } | null>(null);
function say(text: string, kind: FeedbackKind = "info") { notice.value = text; noticeKind.value = kind; }
function sayAI(text: string, kind: FeedbackKind = "info") { aiNotice.value = text; aiNoticeKind.value = kind; }
async function withBusy(key: string, action: () => Promise<void>): Promise<void> { if (busy.value[key]) return; busy.value[key] = true; try { await action(); } finally { busy.value[key] = false; } }
function suggestNext(text: string, to: ModuleName, toLabel: string) { guide.value = { text, to, toLabel }; }
function dismissGuide() { guide.value = null; }
const starLabels: Record<string, string> = { situation: "情境", task: "任务", action: "行动", result: "结果" };
function formatStarMissing(missing: string[]) { return missing.map((item) => starLabels[item] || item).join("、"); }
function starExperiences(check: QualityCheck) { return check.star.experiences ?? check.star.items ?? []; }
function starItemHint(check: QualityCheck, item: StarExperience) {
  const prefix = typeof check.star.total_experiences === "number" ? `这段经历共 ${item.bullet_count ?? 1} 条要点；` : "旧版逐条提醒；";
  return `${prefix}缺少：${formatStarMissing(item.missing)}`;
}
function starSummary(check: QualityCheck) {
  if (typeof check.star.total_experiences === "number") return `共检查 ${check.star.total_experiences} 段经历，${check.star.needs_follow_up} 段需要补充。`;
  return `旧版检查记录：共检查 ${check.star.total_items ?? 0} 条要点，${check.star.needs_follow_up} 条需要补充。`;
}
function layoutExceedsOnePage(check?: QualityCheck) { return (check?.layout?.estimated_pages ?? 1) > 1; }

async function api<T>(path: string, options: RequestInit = {}): Promise<T> { const response = await fetch(path, { headers: { "Content-Type": "application/json", ...(options.headers || {}) }, ...options }); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.detail || `请求失败（${response.status}）`); } return response.status === 204 ? (undefined as T) : response.json(); }
function restoreDraft(run: Run) { currentRun.value = run; selectedSourceId.value = run.source_resume_id; selectedJobId.value = run.input_snapshot.job_id || null; selectedResumeTargetId.value = run.input_snapshot.target_id || null; jdTitle.value = run.input_snapshot.job_title || ""; jdCompany.value = run.input_snapshot.company || ""; jdText.value = run.input_snapshot.jd_text || ""; instruction.value = run.input_snapshot.instruction || ""; }
async function loadRuns() { runs.value = await api<Run[]>("/api/resume-runs"); }
async function loadBossBrowserStatus() { try { bossBrowser.value = await api<BossBrowserStatus>("/api/jobs/boss/browser"); } catch (error) { bossSyncNotice.value = (error as Error).message; } }
async function loadAll() { [sources.value, images.value, knowledge.value, resumes.value, targets.value, jobs.value, runs.value] = await Promise.all([api<ResumeSource[]>("/api/resume-sources"), api<ResumeImage[]>("/api/resume-images"), api<KnowledgeItem[]>("/api/knowledge"), api<ResumeVersion[]>("/api/resumes"), api<Target[]>("/api/targets"), api<Job[]>("/api/jobs"), api<Run[]>("/api/resume-runs")]); const draft = runs.value.find((run) => run.status === "draft" && run.result_content.trim()); if (draft) { restoreDraft(draft); await refreshDraftQuality(); } await loadBossBrowserStatus(); }
function go(module: ModuleName) { active.value = module; location.hash = module; guide.value = null; }
function syncModuleFromHash() { active.value = moduleFromHash(location.hash); }
function selectSource(source: ResumeSource) { selectedSourceId.value = source.id; sourceDraft.value = source.content; sourceFilename.value = source.filename; currentRun.value = null; go("upgrade"); }
function selectJobForUpgrade(event: Event) { const value = (event.target as HTMLSelectElement).value; selectedJobId.value = value ? Number(value) : null; const job = jobs.value.find((item) => item.id === selectedJobId.value); selectedResumeTargetId.value = job?.target_id || null; if (!job) { jdTitle.value = ""; jdCompany.value = ""; jdText.value = ""; return; } jdTitle.value = job.title; jdCompany.value = job.company; jdText.value = job.description; }
function startJobUpgrade(job: Job) { selectedJobId.value = job.id; selectedResumeTargetId.value = job.target_id; jdTitle.value = job.title; jdCompany.value = job.company; jdText.value = job.description; go("upgrade"); }
function startTargetResume(target: Target) { selectedJobId.value = null; selectedResumeTargetId.value = target.id; jdTitle.value = ""; jdCompany.value = ""; jdText.value = ""; title.value = `${target.title}方向简历`; go("upgrade"); }
async function saveSource() { if (!sourceDraft.value.trim()) { say("请粘贴或输入简历文字。", "error"); return; } await withBusy("saveSource", async () => { try { const source = await api<ResumeSource>("/api/resume-sources", { method: "POST", body: JSON.stringify({ filename: sourceFilename.value || "手动粘贴", content: sourceDraft.value }) }); sources.value.unshift(source); selectSource(source); say("原始简历已保存。", "success"); suggestNext("原始简历已保存，可以直接开始优化", "upgrade", "开始优化简历"); } catch (error) { say((error as Error).message, "error"); } }); }
function toBase64(data: ArrayBuffer) { const bytes = new Uint8Array(data); let binary = ""; const chunk = 0x8000; for (let index = 0; index < bytes.length; index += chunk) binary += String.fromCharCode(...bytes.subarray(index, index + chunk)); return btoa(binary); }
async function uploadImages(event: Event) { const files = Array.from((event.target as HTMLInputElement).files || []); if (!files.length) return; await withBusy("uploadImages", async () => { let uploaded = 0; for (const file of files) { try { const image = await api<ResumeImage>("/api/resume-images", { method: "POST", body: JSON.stringify({ filename: file.name, content_type: file.type, content_base64: toBase64(await file.arrayBuffer()) }) }); images.value.unshift(image); uploaded += 1; } catch (error) { say((error as Error).message, "error"); } } if (uploaded) say(`已上传 ${uploaded} 张图片。`, "success"); }); }
async function uploadResumeFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; await withBusy("uploadResumeFile", async () => { try { const source = await api<ResumeSource>("/api/resume-sources/upload", { method: "POST", body: JSON.stringify({ filename: file.name, content_base64: toBase64(await file.arrayBuffer()) }) }); sources.value.unshift(source); sourceDraft.value = source.content; sourceFilename.value = source.filename; selectSource(source); say("文件已解析并保存，可继续优化简历。", "success"); suggestNext("原始简历已保存，可以直接开始优化", "upgrade", "开始优化简历"); } catch (error) { say((error as Error).message, "error"); } }); }
async function recognizeImages() { await withBusy("recognizeImages", async () => { try { const result = await api<{ results: { text: string }[] }>("/api/resume-images/recognize", { method: "POST", body: JSON.stringify({ image_ids: selectedImageIds.value }) }); transcript.value = result.results.map((item) => item.text).filter(Boolean).join("\n\n"); sourceDraft.value = transcript.value; say("图片文字已识别，请校对后保存。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
function clearKnowledgeForm() { editingKnowledgeId.value = null; knowledgeTitle.value = ""; knowledgeOrg.value = ""; knowledgePeriod.value = ""; knowledgeContent.value = ""; knowledgeSource.value = ""; }
function editKnowledge(item: KnowledgeItem) { editingKnowledgeId.value = item.id; knowledgeCategory.value = item.category; knowledgeTitle.value = item.title; knowledgeOrg.value = item.organization; knowledgePeriod.value = item.period; knowledgeContent.value = item.content; knowledgeSource.value = item.source_note; }
async function saveKnowledge() { await withBusy("saveKnowledge", async () => { try { const id = editingKnowledgeId.value; const item = await api<KnowledgeItem>(id ? `/api/knowledge/${id}` : "/api/knowledge", { method: id ? "PUT" : "POST", body: JSON.stringify({ category: knowledgeCategory.value, title: knowledgeTitle.value, organization: knowledgeOrg.value, period: knowledgePeriod.value, content: knowledgeContent.value, source_note: knowledgeSource.value }) }); if (id) knowledge.value = knowledge.value.map((entry) => entry.id === id ? item : entry); else knowledge.value.unshift(item); clearKnowledgeForm(); say("个人资料已保存。", "success"); if (selectedSourceId.value) suggestNext("经历资料已保存", "upgrade", "继续优化简历"); else suggestNext("经历资料已保存", "resume", "准备原始简历"); } catch (error) { say((error as Error).message, "error"); } }); }
async function deleteKnowledge(item: KnowledgeItem) { if (!confirm(`确定删除“${item.title}”吗？`)) return; await withBusy(`deleteKnowledge-${item.id}`, async () => { try { await api(`/api/knowledge/${item.id}`, { method: "DELETE" }); knowledge.value = knowledge.value.filter((entry) => entry.id !== item.id); if (editingKnowledgeId.value === item.id) clearKnowledgeForm(); say("资料已删除。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
async function deleteSource(source: ResumeSource) { if (!confirm(`确定删除原始简历“${source.filename}”吗？已保存的简历版本会保留。`)) return; await withBusy(`deleteSource-${source.id}`, async () => { try { await api(`/api/resume-sources/${source.id}`, { method: "DELETE" }); sources.value = sources.value.filter((entry) => entry.id !== source.id); if (selectedSourceId.value === source.id) { selectedSourceId.value = null; currentRun.value = null; } say("原始简历已删除。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
async function deleteImage(image: ResumeImage) { if (!confirm(`确定删除图片“${image.filename}”吗？`)) return; await withBusy(`deleteImage-${image.id}`, async () => { try { await api(`/api/resume-images/${image.id}`, { method: "DELETE" }); images.value = images.value.filter((entry) => entry.id !== image.id); selectedImageIds.value = selectedImageIds.value.filter((id) => id !== image.id); say("图片已删除。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
async function deleteResume(resume: ResumeVersion) { if (!confirm(`确定删除第 ${resume.version} 版“${resume.title}”吗？`)) return; await withBusy(`deleteResume-${resume.id}`, async () => { try { await api(`/api/resumes/${resume.id}`, { method: "DELETE" }); resumes.value = resumes.value.filter((entry) => entry.id !== resume.id); if (viewedResume.value?.id === resume.id) viewedResume.value = null; say("简历版本已删除。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
async function downloadResume(resume: ResumeVersion, format: "docx" | "pdf" | "md") { await withBusy(`download-${resume.id}-${format}`, async () => { try { const response = await fetch(`/api/resumes/${resume.id}/download?format=${format}`); if (!response.ok) { const body = await response.json().catch(() => ({})); throw new Error(body.detail || `下载失败（${response.status}）`); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${resume.title || `resume-${resume.id}`}.${format}`; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); say(`${format.toUpperCase()} 文件已下载。`, "success"); } catch (error) { say((error as Error).message, "error"); } }); }
const deliveryJob = computed(() => jobs.value.find((item) => item.id === deliveryJobId.value) || null);
const deliveryResumeOptions = computed(() => {
  const job = deliveryJob.value;
  if (!job) return [];
  return resumes.value.filter((resume) => resume.job_snapshot?.job_id === job.id || Boolean(job.target_id && resume.target_id === job.target_id && resume.is_current))
    .sort((first, second) => Number(second.job_snapshot?.job_id === job.id) - Number(first.job_snapshot?.job_id === job.id));
});
const deliveryResume = computed(() => deliveryResumeOptions.value.find((resume) => resume.id === deliveryResumeId.value) || deliveryResumeOptions.value[0] || null);
const deliverySupportsBoss = computed(() => !!deliveryJob.value?.original_url && validBossUrl(deliveryJob.value.original_url));
async function openDeliveryPrep(job: Job) { deliveryJobId.value = job.id; const options = deliveryResumeOptions.value; deliveryResumeId.value = options[0]?.id || null; deliveryGreeting.value = options[0]?.greeting || ""; deliveryNotice.value = options.length ? (options[0].job_snapshot?.job_id === job.id ? "已优先载入该岗位的专属简历。" : "已载入“" + (targets.value.find((target) => target.id === job.target_id)?.title || "当前求职方向") + "”的当前简历。") + (validBossUrl(job.original_url) ? "可以打开 BOSS 沟通页并填入招呼语，发送前仍需你确认。" : "可复制招呼语并下载简历，再通过原始岗位链接手动投递。") : job.target_id ? "该方向还没有当前简历。你可以先为该方向审核保存一份简历，或为这个岗位单独定制。" : "该岗位没有关联求职方向，也没有专属简历；请关联方向或先为岗位定制简历。"; greetingCopied.value = false; await nextTick(); document.querySelector(".delivery-prep")?.scrollIntoView({ behavior: "smooth", block: "start" }); }
function selectDeliveryResume(event: Event) { const id = Number((event.target as HTMLSelectElement).value); deliveryResumeId.value = id || null; const resume = deliveryResumeOptions.value.find((item) => item.id === deliveryResumeId.value); deliveryGreeting.value = resume?.greeting || ""; greetingCopied.value = false; }
async function copyDeliveryGreeting() { if (!deliveryGreeting.value.trim()) { deliveryNotice.value = "打招呼语不能为空。"; return; } try { await navigator.clipboard.writeText(deliveryGreeting.value); greetingCopied.value = true; deliveryNotice.value = "打招呼语已复制，可用作备用粘贴。"; } catch { deliveryNotice.value = "浏览器未允许自动复制，请手动选中文本复制。"; } }
async function openDeliveryJob(): Promise<boolean> { if (!deliveryJob.value?.original_url) { deliveryNotice.value = "这个岗位没有原始岗位链接，请先补充链接。"; return false; } if (!validBossUrl(deliveryJob.value.original_url)) { window.open(deliveryJob.value.original_url, "_blank", "noopener,noreferrer"); deliveryNotice.value = "已打开原始岗位链接。自动填入和发送功能目前仅支持 BOSS 直聘岗位。"; return true; } let ok = true; await withBusy("openDeliveryJob", async () => { try { await api<BossBrowserStatus>("/api/jobs/boss/browser/open-job", { method: "POST", body: JSON.stringify({ url: deliveryJob.value!.original_url }) }); deliveryNotice.value = deliveryResume.value ? "岗位详情已打开。需要进入沟通并填入招呼语时，点击“打开沟通并填入招呼语”。" : "岗位已在专用 Chrome 中打开，请先为该岗位生成并审核保存定制简历。"; } catch (error) { deliveryNotice.value = (error as Error).message; ok = false; } }); return ok; }
async function prepareGreetingInBoss() { const job = deliveryJob.value; const resume = deliveryResume.value; if (!job || !resume) { deliveryNotice.value = "请先选择该岗位的已审核定制简历。"; return; } if (!deliveryGreeting.value.trim()) { deliveryNotice.value = "打招呼语不能为空。"; return; } await withBusy("prepareGreeting", async () => { try { const result = await api<{ message: string }>("/api/jobs/boss/browser/prepare-greeting", { method: "POST", body: JSON.stringify({ job_id: job.id, resume_id: resume.id, greeting: deliveryGreeting.value }) }); deliveryNotice.value = `${result.message}请检查文字后再确认发送。`; } catch (error) { deliveryNotice.value = (error as Error).message; } }); }
async function sendDeliveryGreeting() { const job = deliveryJob.value; const resume = deliveryResume.value; if (!job || !resume) { deliveryNotice.value = "请先选择该岗位的已审核定制简历。"; return; } if (!deliveryGreeting.value.trim()) { deliveryNotice.value = "打招呼语不能为空。"; return; } if (!confirm(`确认向“${job.title} · ${job.company || '未填写公司'}”发送以下打招呼语吗？\n\n${deliveryGreeting.value}`)) return; await withBusy("sendGreeting", async () => { try { await api("/api/jobs/boss/browser/send-greeting", { method: "POST", body: JSON.stringify({ job_id: job.id, resume_id: resume.id, greeting: deliveryGreeting.value, confirmed: true }) }); deliveryNotice.value = "打招呼语已发送。请确认 BOSS 聊天窗口显示成功，再决定是否发送简历附件。"; } catch (error) { deliveryNotice.value = (error as Error).message; } }); }
function downloadDeliveryResume(format: "docx" | "pdf" = "docx") { if (!deliveryResume.value) { deliveryNotice.value = "请先选择该岗位的已审核定制简历。"; return; } downloadResume(deliveryResume.value, format); }
async function sendDeliveryResume() {
  const job = deliveryJob.value; const resume = deliveryResume.value;
  if (!job || !resume) { deliveryNotice.value = "请先选择该岗位的已审核定制简历。"; return; }
  if (!confirm(`确认向“${job.title} · ${job.company || '未填写公司'}”发送定制简历“${resume.title}”吗？`)) return;
  await withBusy("sendResume", async () => {
    try { await api("/api/jobs/boss/browser/send-resume", { method: "POST", body: JSON.stringify({ job_id: job.id, resume_id: resume.id, confirmed: true }) }); deliveryNotice.value = "定制简历附件已发送，请在 BOSS 聊天窗口确认显示成功。"; }
    catch (error) { deliveryNotice.value = (error as Error).message; }
  });
}
async function generateDraft() { if (!selectedSourceId.value) { sayAI("请先选择原始简历。", "error"); return; } if (selectedJobId.value && jdText.value.trim().length < 40) { sayAI("当前岗位记录里的 JD 内容太少，可能只识别到了地点。请补充完整 JD 后再生成，避免基于错误内容定制简历。", "error"); return; } if (!consent.value) { sayAI("请确认允许将资料发送给 DeepSeek。", "error"); return; } await withBusy("generateDraft", async () => { sayAI("AI 正在生成改进草稿，请稍候…"); try { currentRun.value = await api<Run>("/api/resume-runs", { method: "POST", body: JSON.stringify({ source_resume_id: selectedSourceId.value, job_id: selectedJobId.value, target_id: selectedResumeTargetId.value, instruction: instruction.value, job_title: jdTitle.value, company: jdCompany.value, jd_text: jdText.value, allow_external_model: true }) }); await loadRuns(); sayAI("草稿已生成，请检查依据、缺失信息和打招呼语。", "success"); } catch (error) { sayAI((error as Error).message, "error"); try { await loadRuns(); } catch { /* 保留原始生成错误，页面其他数据仍可继续查看。 */ } } }); }
async function refreshDraftQuality() { if (!currentRun.value || !currentRun.value.result_content.trim()) return; try { currentRun.value = await api<Run>(`/api/resume-runs/${currentRun.value.id}/draft`, { method: "PUT", body: JSON.stringify({ result_content: currentRun.value.result_content, greeting: currentRun.value.greeting }) }); sayAI("草稿已重新检查。", "success"); } catch (error) { sayAI((error as Error).message, "error"); } }
async function approveDraft() { const run = currentRun.value; if (!run) return; await withBusy("approveDraft", async () => { try { const runId = run.id; await api(`/api/resume-runs/${runId}/draft`, { method: "PUT", body: JSON.stringify({ result_content: run.result_content, greeting: run.greeting }) }); await api(`/api/resume-runs/${runId}/approve`, { method: "POST", body: JSON.stringify({ title: title.value }) }); sayAI("已审核并保存为新版本。", "success"); currentRun.value = null; runs.value = runs.value.filter((entry) => entry.id !== runId); resumes.value = await api<ResumeVersion[]>("/api/resumes"); suggestNext("简历版本已保存", "jobs", "去管理岗位与投递"); } catch (error) { sayAI((error as Error).message, "error"); } }); }
async function saveTarget() { await withBusy("saveTarget", async () => { try { const item = await api<Target>("/api/targets", { method: "POST", body: JSON.stringify({ title: targetTitle.value, keywords: targetKeywords.value, cities: targetCities.value.split(/[,，]/).map((x) => x.trim()).filter(Boolean) }) }); targets.value.unshift(item); targetTitle.value = ""; say("求职方向已保存。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
async function deleteTarget(target: Target) { if (!confirm(`确定删除求职方向“${target.title}”吗？关联的岗位记录会保留，但会解除方向关联。`)) return; await withBusy(`deleteTarget-${target.id}`, async () => { try { await api(`/api/targets/${target.id}`, { method: "DELETE" }); targets.value = targets.value.filter((item) => item.id !== target.id); jobs.value = jobs.value.map((job) => job.target_id === target.id ? { ...job, target_id: null, target_title: null } : job); say("求职方向已删除，关联岗位记录已保留。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
function clearJobForm() { editingJobId.value = null; jobTitle.value = ""; jobCompany.value = ""; jobCity.value = ""; jobSource.value = "手动录入"; jobUrl.value = ""; jobStatus.value = "未处理"; jobDescription.value = ""; jobNotes.value = ""; jobNextAction.value = ""; jobTargetId.value = null; }
function editJob(job: Job) { editingJobId.value = job.id; jobTitle.value = job.title; jobCompany.value = job.company; jobCity.value = job.city; jobSource.value = job.source; jobUrl.value = job.original_url; jobStatus.value = job.status; jobDescription.value = job.description; jobNotes.value = job.notes; jobNextAction.value = job.next_action; jobTargetId.value = job.target_id; }
async function saveJob() { await withBusy("saveJob", async () => { try { const id = editingJobId.value; const payload = { title: jobTitle.value, company: jobCompany.value, city: jobCity.value, source: jobSource.value, original_url: jobUrl.value, status: jobStatus.value, description: jobDescription.value, notes: jobNotes.value, next_action: jobNextAction.value, target_id: jobTargetId.value }; const item = await api<Job>(id ? `/api/jobs/${id}` : "/api/jobs", { method: id ? "PUT" : "POST", body: JSON.stringify(payload) }); if (id) jobs.value = jobs.value.map((entry) => entry.id === id ? item : entry); else jobs.value.unshift(item); clearJobForm(); say(id ? "岗位已更新。" : "岗位已保存。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
function validBossUrl(value: string) { try { const url = new URL(value); return ["zhipin.com", "www.zhipin.com"].includes(url.hostname) || url.hostname.endsWith(".zhipin.com") ? ["http:", "https:"].includes(url.protocol) : false; } catch { return false; } }
async function parseBossText() { if (!bossPastedText.value.trim()) { bossParseNotice.value = "先粘贴 BOSS 页面文字。"; return; } await withBusy("parseBossText", async () => { try { const result = await api<{ title: string; company: string; city: string; description: string; warnings: string[] }>("/api/jobs/boss/preview", { method: "POST", body: JSON.stringify({ text: bossPastedText.value }) }); if (result.title) bossTitle.value = result.title; if (result.company) bossCompany.value = result.company; if (result.city) bossCity.value = result.city; bossDescription.value = result.description; bossParseNotice.value = result.warnings.join(" "); } catch (error) { bossParseNotice.value = (error as Error).message; } }); }
async function startBossChrome() { await withBusy("startBossChrome", async () => { try { bossBrowser.value = await api<BossBrowserStatus>("/api/jobs/boss/browser/connect", { method: "POST" }); bossSyncNotice.value = "专用 Chrome 已连接。请在该窗口登录 BOSS，再进入职位收藏页面。"; } catch (error) { bossSyncNotice.value = (error as Error).message; } }); }
async function syncBossChrome() { await withBusy("syncBossChrome", async () => { try { const result = await api<BossSyncResult>("/api/jobs/boss/browser/sync", { method: "POST" }); bossBrowser.value = result; bossSyncJobs.value = result.jobs || []; bossSyncNotice.value = [...(result.warnings || []), result.logged_in === false ? "当前页面可能尚未登录，请先登录后再同步。" : ""].filter(Boolean).join(" "); } catch (error) { bossSyncNotice.value = (error as Error).message; } }); }
async function importSyncedBossJob(job: BossSyncJob) { await withBusy(`importSynced-${job.original_url}`, async () => { try { const item = await api<Job>("/api/jobs", { method: "POST", body: JSON.stringify({ title: job.title, company: job.company, city: job.city, source: job.source, original_url: job.original_url, status: "收藏", description: job.description, notes: "从 BOSS 同步岗位，已由用户确认导入。", next_action: "分析 JD 并准备定制简历", target_id: bossTargetId.value }) }); jobs.value.unshift(item); bossSyncJobs.value = bossSyncJobs.value.filter((entry) => entry.original_url !== job.original_url); say("已导入岗位：" + job.title, "success"); suggestNext("岗位已导入", "upgrade", "按该岗位定制简历（可选）"); } catch (error) { say((error as Error).message, "error"); } }); }
async function importBossJob() { if (!bossTitle.value.trim()) { say("请填写 BOSS 岗位名称。", "error"); return; } if (bossUrl.value.trim() && !validBossUrl(bossUrl.value.trim())) { say("岗位链接需要是 BOSS 直聘的 http/https 页面链接。", "error"); return; } await withBusy("importBossJob", async () => { try { const item = await api<Job>("/api/jobs", { method: "POST", body: JSON.stringify({ title: bossTitle.value, company: bossCompany.value, city: bossCity.value, source: "BOSS 直聘（用户导入）", original_url: bossUrl.value, status: "收藏", description: bossDescription.value, notes: "从 BOSS 收藏岗位导入，待审核。", next_action: "分析 JD 并准备定制简历", target_id: bossTargetId.value }) }); jobs.value.unshift(item); bossTitle.value = ""; bossCompany.value = ""; bossCity.value = ""; bossUrl.value = ""; bossDescription.value = ""; bossPastedText.value = ""; bossParseNotice.value = ""; bossTargetId.value = null; say("BOSS 岗位已导入并标记为收藏。", "success"); suggestNext("岗位已导入", "upgrade", "按该岗位定制简历（可选）"); } catch (error) { say((error as Error).message, "error"); } }); }
function openBossJob() { if (!validBossUrl(bossUrl.value.trim())) { say("请填写有效的 BOSS 直聘岗位链接。", "error"); return; } window.open(bossUrl.value.trim(), "_blank", "noopener,noreferrer"); }
async function updateJobStatus(job: Job, event: Event) { const status = (event.target as HTMLSelectElement).value; await withBusy(`updateJobStatus-${job.id}`, async () => { try { const updated = await api<Job>(`/api/jobs/${job.id}`, { method: "PUT", body: JSON.stringify({ ...job, status }) }); jobs.value = jobs.value.map((item) => item.id === job.id ? updated : item); say(`“${job.title}”的跟进状态已更新为${status}。`, "success"); } catch (error) { (event.target as HTMLSelectElement).value = job.status; say((error as Error).message, "error"); } }); }
async function deleteJob(job: Job) { if (!confirm(`确定删除“${job.title}”吗？`)) return; await withBusy(`deleteJob-${job.id}`, async () => { try { await api(`/api/jobs/${job.id}`, { method: "DELETE" }); jobs.value = jobs.value.filter((item) => item.id !== job.id); if (editingJobId.value === job.id) clearJobForm(); say("岗位记录已删除。", "success"); } catch (error) { say((error as Error).message, "error"); } }); }
const selectedSource = computed(() => sources.value.find((item) => item.id === selectedSourceId.value));
const latestTask = computed(() => runs.value[0] || null);
const filteredJobs = computed(() => jobs.value.filter((item) => { const matchesStatus = jobFilterStatus.value === "全部" || item.status === jobFilterStatus.value; const query = jobSearch.value.trim().toLowerCase(); const matchesQuery = !query || `${item.title} ${item.company} ${item.city} ${item.description}`.toLowerCase().includes(query); return matchesStatus && matchesQuery; }));
const workflowSteps = computed<{ id: ModuleName; label: string; done: boolean; hint: string }[]>(() => [
  { id: "resume", label: "准备材料", done: sources.value.length > 0, hint: sources.value.length ? `已保存 ${sources.value.length} 份简历` : "上传或粘贴一份简历" },
  { id: "upgrade", label: "优化简历", done: resumes.value.length > 0, hint: resumes.value.length ? `已保存 ${resumes.value.length} 个版本` : "审核 AI 草稿后保存" },
  { id: "jobs", label: "投递岗位", done: jobs.value.length > 0, hint: jobs.value.length ? `已记录 ${jobs.value.length} 个岗位` : "导入或记录目标岗位" },
]);
const nextWorkflowStep = computed(() => workflowSteps.value.find((step) => !step.done) || workflowSteps.value[workflowSteps.value.length - 1]);
onMounted(() => {
  window.addEventListener("hashchange", syncModuleFromHash);
  loadAll().catch((error) => { say((error as Error).message, "error"); }).finally(() => { loading.value = false; });
});
onBeforeUnmount(() => window.removeEventListener("hashchange", syncModuleFromHash));
</script>

<template>
  <main class="shell">
    <header><div><p class="eyebrow">JOB SEARCH WORKSPACE</p><h1>简历工作台</h1><p class="subtitle">准备简历，生成可审核版本，再管理投递。</p></div><span class="badge">本地保存 · 你来确认</span></header>
    <nav class="module-index" aria-label="求职流程"><a v-for="item in [{id:'resume',label:'准备材料'},{id:'upgrade',label:'优化简历'},{id:'jobs',label:'投递岗位'}]" :key="item.id" :class="{active: active === item.id}" :aria-current="active === item.id ? 'step' : undefined" href="#" @click.prevent="go(item.id as ModuleName)">{{ item.label }}</a><a class="knowledge-link" :class="{active: active === 'knowledge'}" :aria-current="active === 'knowledge' ? 'page' : undefined" href="#" @click.prevent="go('knowledge')">个人知识库 <span>{{ knowledge.length }}</span></a></nav>
    <section class="workflow-overview" aria-label="求职流程进度"><div class="workflow-heading"><div><strong>三步完成求职准备</strong><span>先准备一份简历，其余资料和岗位定制都可选</span></div><button class="workflow-next" @click="go(nextWorkflowStep.id)">{{ nextWorkflowStep.done ? '查看投递岗位' : `下一步：${nextWorkflowStep.label}` }}</button></div><div class="workflow-steps"><button v-for="(step, index) in workflowSteps" :key="step.id" class="workflow-step" :class="{ active: active === step.id, done: step.done }" @click="go(step.id)"><span class="workflow-number">{{ step.done ? '✓' : index + 1 }}</span><span><b>{{ step.label }}</b><small>{{ step.hint }}</small></span></button></div></section>
    <p v-if="loading" class="notice">正在载入工作台数据…</p>
<div v-if="guide" class="next-guide" role="status"><span class="guide-done">✓ {{ guide.text }}</span><span class="guide-next-label">建议下一步</span><button class="primary" @click="go(guide.to); dismissGuide()">{{ guide.toLabel }}</button><button class="link-button" @click="dismissGuide()">知道了</button></div>
<p v-if="notice" :key="notice" :class="['notice', noticeKind]">{{ notice }}</p>
    <p v-if="active === 'upgrade' && latestTask?.status === 'failed'" class="notice" role="alert"><b>最近一次模型调用没有成功。</b> {{ latestTask.error_message || '服务未返回详细原因，请检查后端日志。' }}</p>

    <section v-if="active === 'resume'" class="panel"><h2>准备一份简历</h2><p class="hint">上传或粘贴现有简历即可开始。原稿会单独保留，不会被改进结果覆盖。</p><div class="grid two"><div><label>上传文字型简历文件</label><input type="file" accept=".txt,.md,.pdf,.docx" @change="uploadResumeFile" /><p v-if="busy.uploadResumeFile" class="inline-status">正在解析上传的文件…</p><label>材料名称</label><input v-model="sourceFilename" maxlength="255" /><label>简历文字</label><textarea v-model="sourceDraft" placeholder="也可以直接粘贴简历文字"></textarea><button class="primary" @click="saveSource" :disabled="busy.saveSource">{{ busy.saveSource ? '保存中…' : '保存原始简历' }}</button></div><div><details class="image-import"><summary>图片简历（可选）</summary><label>上传图片简历</label><input type="file" accept="image/png,image/jpeg" multiple @change="uploadImages" /><p v-if="busy.uploadImages" class="inline-status">正在上传图片…</p><div class="image-list"><div v-for="image in images" :key="image.id" class="image-item"><input v-model="selectedImageIds" type="checkbox" :value="image.id" />{{ image.filename }}<img :src="`/api/resume-images/${image.id}/content`" /><button @click="deleteImage(image)" :disabled="busy['deleteImage-' + image.id]">{{ busy['deleteImage-' + image.id] ? '删除中…' : '删除' }}</button></div></div><button @click="recognizeImages" :disabled="!selectedImageIds.length || busy.recognizeImages">{{ busy.recognizeImages ? '识别中…' : '识别选中图片' }}</button><textarea v-model="transcript" placeholder="识别结果会显示在这里，请校对后复制到上方文字框"></textarea></details></div></div><h3>已保存原始简历</h3><div class="card-list"><article v-for="source in sources" :key="source.id" class="card"><button class="link-button" @click="selectSource(source)">{{ source.filename }} · {{ source.content.length }} 字</button><button @click="deleteSource(source)" :disabled="busy['deleteSource-' + source.id]">{{ busy['deleteSource-' + source.id] ? '删除中…' : '删除原稿' }}</button></article><p v-if="!sources.length" class="muted">还没有原始简历。</p></div><div class="optional-step"><div><strong>个人知识库 <span class="optional-label">可选补充</span></strong><span>{{ knowledge.length ? `已保存 ${knowledge.length} 条经历资料` : "保存工作、项目和技能经历，为简历优化提供依据" }}</span></div><button @click="go('knowledge')">{{ knowledge.length ? "打开知识库" : "补充经历" }}</button></div></section>

    <section v-else-if="active === 'knowledge'" class="panel"><button class="link-button back-link" @click="go('resume')">← 返回准备材料</button><h2>个人知识库 <span class="optional-label">可选补充</span></h2><p class="hint">集中保存教育、工作、项目、技能和成果经历。简历优化时会参考这些资料，帮助突出原稿里没有写清楚的真实内容。</p><div class="grid two"><div><label>资料类型</label><select v-model="knowledgeCategory"><option>个人信息</option><option>教育经历</option><option>工作经历</option><option>项目经验</option><option>技能</option><option>成果</option></select><label>条目名称</label><input v-model="knowledgeTitle" placeholder="例如：智能问答项目" /><label>学校、公司或项目</label><input v-model="knowledgeOrg" /><label>时间</label><input v-model="knowledgePeriod" /><label>详情</label><textarea v-model="knowledgeContent" placeholder="职责、技术、结果和可验证数据"></textarea><label>来源说明</label><input v-model="knowledgeSource" placeholder="本人填写或材料来源" /><button class="primary" @click="saveKnowledge" :disabled="busy.saveKnowledge">{{ busy.saveKnowledge ? '保存中…' : (editingKnowledgeId ? '保存修改' : '保存资料') }}</button><button v-if="editingKnowledgeId" @click="clearKnowledgeForm">取消修改</button></div><div class="card-list"><article v-for="item in knowledge" :key="item.id" class="card"><strong>#{{ item.id }} · {{ item.title }}</strong><span>{{ item.category }} · {{ item.organization }} · {{ item.period }}</span><p>{{ item.content }}</p><button @click="editKnowledge(item)">编辑</button> <button @click="deleteKnowledge(item)" :disabled="busy['deleteKnowledge-' + item.id]">{{ busy['deleteKnowledge-' + item.id] ? '删除中…' : '删除' }}</button></article><p v-if="!knowledge.length" class="muted">还没有资料。</p></div></div></section>

    <section v-else-if="active === 'upgrade'" class="panel"><h2>让简历更贴合目标岗位</h2><p class="hint">选好原稿并生成草稿。你可以先直接生成，之后再按岗位定制。</p><p class="hint">{{ selectedSource ? `当前原稿：${selectedSource.filename}` : '先从上传简历模块选择原始简历。' }}</p><p v-if="!knowledge.length" class="muted optional-hint">没有补充经历也可以继续，草稿会依据原始简历生成。</p><div class="card-list"><button v-for="source in sources" :key="source.id" class="card" @click="selectSource(source)">{{ source.filename }}</button></div><div v-if="selectedSource" class="upgrade"><details class="advanced-options" :open="Boolean(selectedJobId || jdText.trim() || jdTitle.trim())"><summary>按具体岗位定制（可选）</summary><div class="advanced-fields"><label>简历所属求职方向</label><select v-model="selectedResumeTargetId"><option :value="null">不关联方向（只保存为普通版本）</option><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.title }}</option></select><p class="muted">关联方向后，无岗位 JD 的版本可作为该方向当前简历；选了具体岗位后，新版本仅属于该岗位，不会替换方向简历。</p><label>从已保存岗位载入（可选）</label><select :value="selectedJobId || ''" @change="selectJobForUpgrade"><option value="">手动填写 JD</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{ job.title }} · {{ job.company || '未填写公司' }} · {{ job.city || '未填写城市' }}</option></select><label>岗位名称（可选）</label><input v-model="jdTitle" placeholder="例如：AI 应用开发工程师" /><label>公司（可选）</label><input v-model="jdCompany" /><label>岗位 JD（可选）</label><textarea v-model="jdText" placeholder="粘贴岗位职责、任职要求和关键词"></textarea><p v-if="selectedJobId && jdText.trim().length < 40" class="notice">当前岗位 JD 内容过短，可能只识别到了地点。请先补充完整 JD，避免生成错误的定制简历。</p><label>改进重点（可选）</label><input v-model="instruction" placeholder="例如：突出 Agent 项目，控制在一页" /></div></details><label class="check"><input v-model="consent" type="checkbox" />我同意将简历及所选资料发送给 DeepSeek</label><button class="primary" @click="generateDraft" :disabled="busy.generateDraft || (Boolean(selectedJobId) && jdText.trim().length < 40)">{{ busy.generateDraft ? 'AI 生成中…' : '生成 AI 改进草稿' }}</button><div v-if="busy.generateDraft" class="ai-status" role="status" aria-live="polite"><span class="spinner" aria-hidden="true"></span><div><b>AI 正在生成改进草稿…</b><small>通常需要十几秒到一分钟（含 JD 分析、资料检索和模型生成），完成后会自动展示草稿，请勿刷新页面。</small></div></div><p :key="aiNotice" :class="['notice', aiNoticeKind]">{{ aiNotice }}</p><div v-if="currentRun" class="review"><details class="review-details"><summary>查看岗位分析与匹配</summary><div v-if="currentRun.input_snapshot?.agent_graph" class="agent-graph-status"><h3>Agent 流程状态</h3><p><b>{{ currentRun.input_snapshot.agent_graph.name }}</b>：{{ currentRun.input_snapshot.agent_graph.status_message }}</p><span class="muted">状态：{{ currentRun.input_snapshot.agent_graph.status }}</span></div><div v-if="currentRun.input_snapshot?.jd_analysis" class="jd-review"><h3>JD 要求分析（本地整理）</h3><p class="muted">当前版本使用明确标题和关键词进行规则分类，作为审核辅助。</p><div class="grid two"><div><h4>岗位职责</h4><ul><li v-for="entry in currentRun.input_snapshot.jd_analysis.responsibilities" :key="entry">{{ entry }}</li><li v-if="!currentRun.input_snapshot.jd_analysis.responsibilities.length">未识别到明确职责条目</li></ul><h4>硬性要求</h4><ul><li v-for="entry in currentRun.input_snapshot.jd_analysis.hard_requirements" :key="entry">{{ entry }}</li><li v-if="!currentRun.input_snapshot.jd_analysis.hard_requirements.length">未识别到明确要求</li></ul></div><div><h4>优先条件</h4><ul><li v-for="entry in currentRun.input_snapshot.jd_analysis.preferred_qualifications" :key="entry">{{ entry }}</li><li v-if="!currentRun.input_snapshot.jd_analysis.preferred_qualifications.length">未识别到明确优先条件</li></ul><h4>关键词</h4><p>{{ currentRun.input_snapshot.jd_analysis.keywords.join('、') || '未提取到关键词' }}</p></div></div><h3>要求与个人资料匹配</h3><div class="card-list"><article v-for="(match, index) in currentRun.input_snapshot.requirement_matches" :key="`${match.category}-${index}`" class="card"><strong>{{ match.category }} · {{ match.status }}</strong><p>{{ match.requirement }}</p><p v-if="match.evidence.length">相关依据：<span v-for="item in match.evidence" :key="`${item.knowledge_item_id}-${item.title}`">{{ item.knowledge_item_id ? `个人资料 #${item.knowledge_item_id}` : item.title }}（命中：{{ item.matched_terms.join('、') }}） </span></p><p v-else class="muted">原始简历和个人知识库中都未找到关键词线索，请人工核对。</p></article><p v-if="!currentRun.input_snapshot.requirement_matches?.length" class="muted">没有提供 JD，跳过岗位要求匹配。</p></div></div></details><h3>修改前后对照</h3><div class="compare-grid"><div><h4>原始简历</h4><pre class="resume-preview">{{ selectedSource.content }}</pre></div><div><h4>改进草稿（可编辑）</h4><textarea v-model="currentRun.result_content" @blur="refreshDraftQuality"></textarea></div></div><details class="review-details"><summary>查看质量检查与修改摘要</summary><div v-if="currentRun.input_snapshot.quality_check" class="quality-check"><h3>STAR 检查</h3><p class="muted">这是按完整工作或项目经历汇总的关键词提醒，不要求每条要点单独满足 STAR。情境和任务可由经历背景体现，行动与结果可以分布在同一段经历的多条要点中；请结合原始资料人工确认。</p><p><b>结果：</b>{{ currentRun.input_snapshot.quality_check.star.status }}；{{ starSummary(currentRun.input_snapshot.quality_check) }}</p><p v-if="currentRun.input_snapshot.quality_check.layout" class="layout-check" :class="{ over: currentRun.input_snapshot.quality_check.layout.estimated_pages > 1 }"><b>一页检查：</b>{{ currentRun.input_snapshot.quality_check.layout.status }}（估算 {{ currentRun.input_snapshot.quality_check.layout.estimated_lines }} / {{ currentRun.input_snapshot.quality_check.layout.max_lines }} 行）。{{ currentRun.input_snapshot.quality_check.layout.message }}</p><ul><li v-for="item in starExperiences(currentRun.input_snapshot.quality_check)" :key="item.text"><strong v-if="item.title">{{ item.title }}</strong><p>{{ item.text }}</p><span class="muted">{{ starItemHint(currentRun.input_snapshot.quality_check, item) }}</span></li><li v-if="!starExperiences(currentRun.input_snapshot.quality_check).length" class="muted">暂未发现明显 STAR 缺口，仍需人工核对。</li></ul><h3>修改摘要</h3><p>新增 {{ currentRun.input_snapshot.quality_check.diff.added_lines }} 行，删除 {{ currentRun.input_snapshot.quality_check.diff.removed_lines }} 行。</p><details v-if="currentRun.input_snapshot.quality_check.diff.added_preview.length"><summary>查看新增内容</summary><ul><li v-for="line in currentRun.input_snapshot.quality_check.diff.added_preview" :key="`add-${line}`">{{ line }}</li></ul></details><details v-if="currentRun.input_snapshot.quality_check.diff.removed_preview.length"><summary>查看删除内容</summary><ul><li v-for="line in currentRun.input_snapshot.quality_check.diff.removed_preview" :key="`remove-${line}`">{{ line }}</li></ul></details><div class="fact-check"><h3>疑似无依据内容</h3><p class="muted">{{ currentRun.input_snapshot.quality_check.factuality?.scope || '检查仅覆盖数字和常见技术名词；其他事实仍需人工核对。' }}</p><p><b>结果：</b>{{ currentRun.input_snapshot.quality_check.factuality?.status || '待检查' }}</p><ul><li v-for="item in currentRun.input_snapshot.quality_check.factuality?.items || []" :key="item.text"><strong>{{ item.claims.join('、') }}</strong>：{{ item.text }}</li><li v-if="!currentRun.input_snapshot.quality_check.factuality" class="muted">该草稿尚未运行此项检查；请编辑草稿后重新检查。</li><li v-else-if="!currentRun.input_snapshot.quality_check.factuality.items.length" class="muted">未发现新增数字或常见技术名词；其他事实仍需人工核对。</li></ul></div></div></details><h3>打招呼语（可编辑）</h3><textarea v-model="currentRun.greeting" class="short-text"></textarea><details class="review-details"><summary>查看检索依据与待确认信息</summary><h3>RAG 检索到的简历片段</h3><p class="muted">系统先从原始简历和个人资料中挑选相关内容，再把这些依据交给模型；“关键词匹配”表示命中岗位词，“备用片段”表示没有词面重合，需重点人工核对。</p><div class="card-list"><article v-for="chunk in currentRun.input_snapshot.resume_chunks || []" :key="chunk.chunk_id" class="card"><strong>原始简历片段 #{{ chunk.chunk_id }} · {{ chunk.match_type === 'keyword' ? `关键词匹配：${chunk.matched_terms.join('、')}` : chunk.match_type === 'fallback' ? '备用片段，需人工核对' : '通用背景片段' }}</strong><p>{{ chunk.content }}</p></article><p v-if="!currentRun.input_snapshot.resume_chunks?.length" class="muted">本次没有检索到原始简历片段。</p></div><h3>模型引用的事实依据</h3><ul><li>原始简历：{{ selectedSource?.filename || '当前简历原稿' }}（本次改进的主要资料来源）</li><li v-for="(item, index) in currentRun.evidence" :key="`${item.knowledge_item_id || item.resume_chunk_id}-${index}`">{{ item.knowledge_item_id ? `个人资料 #${item.knowledge_item_id}` : `原始简历片段 #${item.resume_chunk_id}` }}：{{ item.used_for }}</li><li v-if="!knowledge.length" class="muted">尚未填写个人知识库，当前草稿只基于原始简历；请逐项核对。</li><li v-else-if="!currentRun.evidence.length" class="muted">模型没有引用个人知识库条目，请逐项核对。</li></ul><h3>待确认信息</h3><ul><li v-for="item in currentRun.missing_info" :key="item">{{ item }}</li><li v-if="!currentRun.missing_info.length">未标记缺口，仍需人工检查。</li></ul></details><label>保存版本名称</label><input v-model="title" /><button class="primary" :disabled="busy.approveDraft || layoutExceedsOnePage(currentRun.input_snapshot.quality_check)" @click="approveDraft">{{ busy.approveDraft ? '保存中…' : '审核通过并保存' }}</button></div></div><h3>已保存简历版本</h3><div class="card-list"><article v-for="resume in resumes" :key="resume.id" class="card"><strong>第 {{ resume.version }} 版 · {{ resume.title }}</strong><p>{{ resume.content.slice(0, 160) }}</p><p v-if="resume.job_snapshot?.job_title" class="muted">关联岗位：{{ resume.job_snapshot.job_title }} · {{ resume.job_snapshot.company || "未填写公司" }}</p><p v-if="resume.greeting"><b>打招呼语：</b>{{ resume.greeting }}</p><button @click="viewedResume = viewedResume?.id === resume.id ? null : resume">{{ viewedResume?.id === resume.id ? '收起' : '查看全文' }}</button> <button @click="downloadResume(resume, 'docx')" :disabled="busy['download-' + resume.id + '-docx']">{{ busy['download-' + resume.id + '-docx'] ? '下载中…' : '下载 DOCX' }}</button> <button @click="downloadResume(resume, 'md')" :disabled="busy['download-' + resume.id + '-md']">{{ busy['download-' + resume.id + '-md'] ? '下载中…' : '下载 Markdown' }}</button> <button @click="deleteResume(resume)" :disabled="busy['deleteResume-' + resume.id]">{{ busy['deleteResume-' + resume.id] ? '删除中…' : '删除版本' }}</button><pre v-if="viewedResume?.id === resume.id">{{ resume.content }}</pre></article><p v-if="!resumes.length" class="muted">确认草稿后会保存在这里。</p></div></section>

    <section v-else-if="active === 'targets'" class="panel"><h2>求职方向</h2><p class="hint">每个方向维护一份当前简历；同方向岗位默认复用，只有差异明显时再单独定制。</p><div class="grid two"><div><label>岗位名称</label><input v-model="targetTitle" /><label>关键词</label><input v-model="targetKeywords" /><label>城市（逗号分隔）</label><input v-model="targetCities" /><button class="primary" @click="saveTarget" :disabled="busy.saveTarget">{{ busy.saveTarget ? '保存中…' : '保存方向' }}</button></div><div class="card-list"><article v-for="item in targets" :key="item.id" class="card"><strong>{{ item.title }}</strong><span>{{ item.cities.join('、') }} · {{ item.keywords || '未填写关键词' }}</span><p>当前简历：{{ resumes.find((resume) => resume.target_id === item.id && resume.is_current)?.title || '尚未设置' }}</p><button class="primary" @click="startTargetResume(item)">{{ resumes.some((resume) => resume.target_id === item.id && resume.is_current) ? '更新此方向简历' : '为此方向生成简历' }}</button> <button @click="deleteTarget(item)" :disabled="busy['deleteTarget-' + item.id]">{{ busy['deleteTarget-' + item.id] ? '删除中…' : '删除方向' }}</button></article></div></div></section>
    <section v-else class="panel"><div class="jobs-heading"><div><h2>管理岗位与投递</h2><p class="hint">先记录目标岗位，再准备简历并跟进进度；其他导入方式可按需展开。</p></div><button @click="go('targets')">管理求职方向</button></div><article v-if="deliveryJob" class="import-card delivery-prep"><h3>投递准备：{{ deliveryJob.title }}</h3><p class="muted">{{ deliveryJob.company || '未填写公司' }} · {{ deliveryJob.city || '未填写城市' }}</p><p v-if="deliverySupportsBoss" class="muted">点击下方按钮后，专用 Chrome 会打开此岗位的沟通页并填入招呼语；这一步不会发送消息。确认招呼语和简历后，再分别点击发送。</p><p v-else class="muted">此岗位可正常记录和管理。你可以打开原始链接、复制招呼语并下载简历，再手动完成投递。</p><details><summary>查看岗位 JD</summary><pre class="resume-preview delivery-jd">{{ deliveryJob.description }}</pre></details><div v-if="deliveryResumeOptions.length"><label>投递简历（优先岗位专属版，否则使用方向当前版）</label><select :value="deliveryResume?.id || ''" @change="selectDeliveryResume"><option v-for="resume in deliveryResumeOptions" :key="resume.id" :value="resume.id">第 {{ resume.version }} 版 · {{ resume.title }}{{ resume.job_snapshot?.job_id === deliveryJob.id ? '（岗位专属）' : '（方向当前版）' }}</option></select><p class="muted">所有可选版本都已审核保存。你可以为不同岗位复用方向简历，也可以手动选择岗位专属版本。</p><template v-if="deliverySupportsBoss"><label>打招呼语（发送前可修改）</label><textarea v-model="deliveryGreeting" class="short-text"></textarea><div class="card-actions"><button class="primary" @click="prepareGreetingInBoss" :disabled="busy.prepareGreeting">{{ busy.prepareGreeting ? '正在打开沟通页并填入…' : '打开沟通并填入招呼语' }}</button><button @click="sendDeliveryGreeting" :disabled="busy.sendGreeting">{{ busy.sendGreeting ? '发送中…' : '确认并发送打招呼语' }}</button><button @click="copyDeliveryGreeting">{{ greetingCopied ? '已复制' : '复制备用' }}</button><button @click="downloadDeliveryResume()" :disabled="busy['download-' + deliveryResume?.id + '-docx']">{{ busy['download-' + deliveryResume?.id + '-docx'] ? '下载中…' : '下载定制简历 DOCX' }}</button><button @click="sendDeliveryResume" :disabled="busy.sendResume">{{ busy.sendResume ? '发送中…' : '确认并发送简历附件' }}</button><button v-if="deliveryJob.original_url" @click="openDeliveryJob" :disabled="busy.openDeliveryJob">{{ busy.openDeliveryJob ? '打开中…' : '只打开岗位详情' }}</button></div><p class="notice">打开沟通页和填入招呼语不会发送消息。招呼语与简历附件仍需分别确认后发送。</p></template><template v-else><label>打招呼语（可复制）</label><textarea v-model="deliveryGreeting" class="short-text"></textarea><div class="card-actions"><button @click="copyDeliveryGreeting">{{ greetingCopied ? "已复制" : "复制招呼语" }}</button><button @click="downloadDeliveryResume('pdf')" :disabled="busy['download-' + deliveryResume?.id + '-pdf']">{{ busy['download-' + deliveryResume?.id + '-pdf'] ? '下载中…' : '下载一页 PDF' }}</button><button v-if="deliveryJob.original_url" @click="openDeliveryJob" :disabled="busy.openDeliveryJob">{{ busy.openDeliveryJob ? '打开中…' : '打开原始岗位链接' }}</button></div><p class="notice">自动填入和发送功能目前仅支持 BOSS 直聘岗位；其他岗位可手动使用以上材料投递。</p></template></div><div v-else><p class="notice">当前没有可用简历。请关联求职方向并为该方向审核保存简历，或为此岗位单独定制。</p><button class="primary" @click="startJobUpgrade(deliveryJob)">为此岗位定制简历</button></div><p v-if="deliveryNotice" class="notice">{{ deliveryNotice }}</p></article><details class="secondary-tools"><summary>更多导入方式：Chrome 同步、粘贴岗位或手动录入</summary><article class="import-card chrome-card"><h3>Chrome 同步收藏岗位</h3><p class="muted">在专用 Chrome 中打开 BOSS“职位收藏”，点击“同步当前收藏页”。结果会先预览，逐条确认后再导入。也可以粘贴 BOSS 页面文字或手动录入。</p><p class="chrome-status"><b>自动同步状态：</b>{{ bossBrowser.message }}<span v-if="bossBrowser.url"> · {{ bossBrowser.url }}</span></p><div class="card-actions"><button class="primary" @click="startBossChrome" :disabled="busy.startBossChrome">{{ busy.startBossChrome ? '连接中…' : '连接专用 Chrome' }}</button><button class="primary" @click="syncBossChrome" :disabled="!bossBrowser.connected || busy.syncBossChrome">{{ busy.syncBossChrome ? '同步中…' : '同步当前收藏页' }}</button></div><p v-if="bossSyncNotice" class="notice">{{ bossSyncNotice }}</p><div v-if="bossSyncJobs.length" class="card-list sync-preview"><article v-for="item in bossSyncJobs" :key="item.original_url" class="card"><label>岗位名称</label><input v-model="item.title" /><label>公司</label><input v-model="item.company" placeholder="未识别时请补充" /><label>城市</label><input v-model="item.city" placeholder="未识别时请补充" /><label>岗位 JD（来自完整详情，请核对）</label><textarea v-model="item.description"></textarea><p v-if="item.description.trim().length < 40" class="notice">JD 内容不足，请保留完整岗位职责和任职要求后再导入。</p><ul v-if="item.warnings?.length" class="muted"><li v-for="warning in item.warnings" :key="warning">{{ warning }}</li></ul><details v-if="item.raw_text"><summary>查看页面原始文字</summary><pre class="resume-preview">{{ item.raw_text }}</pre></details><a :href="item.original_url" target="_blank" rel="noreferrer">打开岗位详情核对</a><div class="card-actions"><button class="primary" @click="importSyncedBossJob(item)" :disabled="item.description.trim().length < 40 || busy['importSynced-' + item.original_url]">{{ busy['importSynced-' + item.original_url] ? '导入中…' : '确认导入' }}</button></div></article></div></article><article class="import-card"><h3>从 BOSS 收藏岗位导入</h3><p class="muted">也可把 BOSS 岗位详情文字粘贴到下方并整理，核对后再导入。这种方式无需连接专用 Chrome，也不会自动投递。</p><label>粘贴 BOSS 岗位页面文字</label><textarea v-model="bossPastedText" placeholder="复制岗位页面上的文字粘贴到这里"></textarea><button @click="parseBossText" :disabled="busy.parseBossText">{{ busy.parseBossText ? '解析中…' : '整理岗位信息' }}</button><p v-if="bossParseNotice" class="muted">{{ bossParseNotice }}</p><div class="grid two"><div><label>岗位名称</label><input v-model="bossTitle" placeholder="例如：AI 应用开发工程师" /><label>公司</label><input v-model="bossCompany" /><label>城市</label><input v-model="bossCity" placeholder="例如：北京" /><label>关联求职方向（可选）</label><select v-model="bossTargetId"><option :value="null">暂不关联</option><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.title }}</option></select></div><div><label>BOSS 岗位链接（可选）</label><input v-model="bossUrl" type="url" placeholder="https://www.zhipin.com/..." /><label>整理后的岗位 JD（可编辑）</label><textarea v-model="bossDescription"></textarea><button @click="openBossJob">打开 BOSS 岗位</button> <button class="primary" @click="importBossJob" :disabled="busy.importBossJob">{{ busy.importBossJob ? '导入中…' : '导入并标记为收藏' }}</button></div></div></article></details><div class="grid two"><div><details class="manual-entry"><summary>手动录入岗位</summary><label>岗位名称</label><input v-model="jobTitle" /><label>公司</label><input v-model="jobCompany" /><label>城市</label><input v-model="jobCity" /><label>关联求职方向（可选）</label><select v-model="jobTargetId"><option :value="null">暂不关联</option><option v-for="target in targets" :key="target.id" :value="target.id">{{ target.title }}</option></select><label>来源</label><input v-model="jobSource" /><label>原始岗位链接（可选）</label><input v-model="jobUrl" type="url" placeholder="https://..." /><label>初始跟进状态</label><select v-model="jobStatus"><option>未处理</option><option>收藏</option><option>不合适</option><option>已投递</option><option>面试中</option><option>已结束</option></select><label>岗位描述 / JD</label><textarea v-model="jobDescription"></textarea><label>备注（可选）</label><textarea v-model="jobNotes" class="short-text" placeholder="例如：招聘者回复、岗位疑点"></textarea><label>下一步行动（可选）</label><input v-model="jobNextAction" placeholder="例如：周五前准备定制简历" /><button class="primary" @click="saveJob" :disabled="busy.saveJob">{{ busy.saveJob ? '保存中…' : (editingJobId ? '保存岗位修改' : '保存岗位') }}</button><button v-if="editingJobId" @click="clearJobForm">取消编辑</button></details></div><div><div class="job-filters"><label>筛选状态</label><select v-model="jobFilterStatus"><option>全部</option><option>未处理</option><option>收藏</option><option>不合适</option><option>已投递</option><option>面试中</option><option>已结束</option></select><label>搜索岗位或公司</label><input v-model="jobSearch" placeholder="输入关键词" /></div><div class="card-list"><article v-for="item in filteredJobs" :key="item.id" class="card job-card"><details><summary class="job-summary"><span><strong>{{ item.title }}</strong><small>{{ item.company || '未填写公司' }} · {{ item.city || '未填写城市' }}</small></span><span class="job-status">{{ item.status }}</span></summary><div class="job-card-body"><p v-if="item.target_title" class="muted">求职方向：{{ item.target_title }}</p><label>跟进状态</label><select :value="item.status" @change="updateJobStatus(item, $event)"><option>未处理</option><option>收藏</option><option>不合适</option><option>已投递</option><option>面试中</option><option>已结束</option></select><p v-if="item.source">来源：{{ item.source }}</p><p v-if="item.next_action"><b>下一步：</b>{{ item.next_action }}</p><p v-if="item.notes"><b>备注：</b>{{ item.notes }}</p><details v-if="item.description" class="job-description"><summary>查看岗位描述 / JD</summary><p>{{ item.description }}</p></details><a v-if="item.original_url" :href="item.original_url" target="_blank" rel="noreferrer">查看原始岗位链接</a><div class="card-actions"><button @click="openDeliveryPrep(item)">投递准备</button><button @click="startJobUpgrade(item)">用此岗位定制简历</button><button @click="editJob(item)">编辑</button><button @click="deleteJob(item)" :disabled="busy['deleteJob-' + item.id]">{{ busy['deleteJob-' + item.id] ? '删除中…' : '删除' }}</button></div></div></details></article><p v-if="jobs.length && !filteredJobs.length" class="muted">没有符合筛选条件的岗位。</p><p v-if="!jobs.length" class="muted">还没有岗位记录。</p></div></div></div></section>
  </main>
</template>









